def S(kind,say,**v): v['kind']=kind; return dict(v=v,say=say)
L=[]
# 1 BIG-O
L.append(dict(id='c01-big-o',title='Big-O: How Work Grows',used=['all'],scenes=[
 S('title',['Welcome, Chandra. This lesson is about Big O, the language interviewers use to talk about speed.','No math degree needed. We will use everyday pictures first.'],title='Big-O: How Work Grows',sub='Recipes that scale (or do not)'),
 S('analogy',['Imagine you are handing out name badges at a conference.','If you just hand each guest the top badge from a pile, every guest takes the same tiny effort. That is constant time, written O of one.','If you must search the whole pile for each guest\'s name, the effort grows with the number of guests. That is linear, O of n.','And if every guest must shake hands with every other guest, the work explodes. That is O of n squared.'],text='Handing out badges: grab the top one (O(1)), search the pile (O(n)), or everyone shakes everyone\'s hand (O(n²)).',icons=['O(1)','O(n)','O(n²)']),
 S('chart',['Here is the picture that matters.','The green line is constant: it does not care how big the input is.','Log n grows very slowly. Doubling the input adds just one more step, like guessing a page in a book by halving.','Linear grows in a straight line.','n log n is what good sorting costs.','And n squared shoots off the chart. With a hundred thousand items, that is ten billion steps.'],title='Growth curves'),
 S('bullets',['Big O describes the shape of the growth, not the exact seconds.','We drop constants. Two n and n are both O of n, because the shape is the same.','We keep only the biggest term. n squared plus n is just O of n squared.','Space complexity uses the same language for memory.','For your systems work, also remember that constants still matter in the real world: cache misses, allocations, and locks.'],title='The rules',items=['Shape, not seconds','Drop constants: O(2n) = O(n)','Keep the biggest term: O(n² + n) = O(n²)','Space uses the same notation','Real systems: constants (cache misses, locks) still matter']),
 S('array',['Let us count the work in a real loop.','Scanning an array once touches each cell once. Eight items, eight steps. That is O of n.','A nested loop that compares every pair touches about n squared over two pairs. Eight items, twenty eight pairs.','Binary search on sorted data cuts the range in half each step. Eight items, only three steps.'],title='Counting steps',states=[dict(a=[3,8,1,9,4,7,2,6],ptr={'i':0},note='one pass: 8 steps → O(n)'),dict(a=[3,8,1,9,4,7,2,6],ptr={'i':7},note='each cell touched once'),dict(a=[3,8,1,9,4,7,2,6],ptr={'i':0,'j':5},note='all pairs: 28 → O(n²)'),dict(a=[1,2,3,4,6,7,8,9],ptr={'lo':0,'mid':3,'hi':7},note='halving: 3 steps → O(log n)')]),
 S('bullets',['Here is a handy cheat sheet for interviews.','If n is up to about ten thousand, n squared might pass.','If n is a hundred thousand or a million, aim for n log n or n.','If n is tiny, like twenty, even two to the n, exponential search, can work.','Always say the complexity out loud after you code. It is one of the easiest points to earn.'],title='Interview cheat sheet',items=['n ≤ 10⁴ → O(n²) may be OK','n ≤ 10⁶ → need O(n log n) or O(n)','n ≤ 20 → O(2ⁿ) backtracking OK','Say time AND space out loud']),
 S('title',['That is Big O. Next, open any problem in this course and you will see its brute force and optimal cost side by side.'],title='Recap',sub='Shape of growth • drop constants • biggest term wins'),
]))
# 2 ARRAYS + TWO POINTERS + SLIDING WINDOW
L.append(dict(id='c02-arrays-pointers',title='Arrays, Two Pointers & Sliding Windows',used=['p01-two-sum','p02-longest-substring','p03-container-water','p16-rotated-search'],scenes=[
 S('title',['This lesson covers arrays and two of the most common interview patterns: two pointers and sliding windows.'],title='Arrays, Two Pointers & Sliding Windows',sub='Fingers on a row of boxes'),
 S('analogy',['An array is a row of numbered lockers in a hallway.','Because the lockers are numbered and side by side in memory, you can walk straight to locker number five without opening the others.','That is why reading any index is O of one.','But inserting a locker in the middle means shifting every locker after it, which is O of n.'],text='An array is a row of numbered lockers. Jump to any number instantly; inserting in the middle means shifting everyone down.',icons=['index → O(1)','insert → O(n)']),
 S('array',['Here is an array in memory.','Index zero holds three, index one holds eight, and so on.','Reading index four is a single step: start address plus four times the element size.','This is also why arrays are cache friendly, something you already know from driver code with DMA buffers.'],title='Contiguous memory',states=[dict(a=[3,8,1,9,4,7],note='contiguous cells'),dict(a=[3,8,1,9,4,7],hl=[4],ptr={'i':4},note='address = base + 4 × size')]),
 S('array',['Now, two pointers.','Put one finger at the left end and one at the right end.','At every step, move one finger inward based on a rule.','Because each finger only moves in one direction, the total work is linear.','Container With Most Water uses exactly this: always move the finger at the shorter wall.'],title='Two pointers from both ends',states=[dict(a=[1,8,6,2,5,4,8,3,7],ptr={'l':0,'r':8},note='area = min(1,7) × 8 = 8'),dict(a=[1,8,6,2,5,4,8,3,7],ptr={'l':1,'r':8},hl=[1,8],note='area = min(8,7) × 7 = 49 ★'),dict(a=[1,8,6,2,5,4,8,3,7],ptr={'l':1,'r':7},note='move the shorter side'),dict(a=[1,8,6,2,5,4,8,3,7],ptr={'l':1,'r':6},note='never move backwards → O(n)')]),
 S('array',['A sliding window is two pointers that both move to the right, like a caterpillar.','The right end grows the window. The left end shrinks it when a rule breaks.','For the longest substring without repeats, when the head finds a letter already in the body, the tail jumps past the old copy.','Each letter enters and leaves the window at most once, so it is O of n.'],title='Sliding window (caterpillar)',states=[dict(a=list('abcabcbb'),ptr={'L':0,'R':0},hl=[0],note='window "a"'),dict(a=list('abcabcbb'),ptr={'L':0,'R':2},hl=[0,1,2],note='"abc" length 3'),dict(a=list('abcabcbb'),ptr={'L':1,'R':3},hl=[1,2,3],note='repeat a → tail jumps'),dict(a=list('abcabcbb'),ptr={'L':5,'R':7},hl=[7],note='best stays 3')]),
 S('bullets',['How do you spot these patterns?','If the input is sorted, or you need a pair, think two pointers.','If the question says longest, shortest, or contiguous subarray, think sliding window.','Watch the pitfalls: off by one on window length, and pointers that move backwards.'],title='Spotting the pattern',items=['Sorted input or pairs → two pointers','"Contiguous / longest / shortest" → sliding window','Window length = right − left + 1','Pointers only move forward']),
 S('title',['Try Two Sum, Longest Substring, and Container With Most Water in the practice tab, and watch the pointers move in the visualizer.'],title='Recap',sub='Arrays: O(1) index • Two pointers • Sliding window'),
]))
# 3 HASH TABLES
L.append(dict(id='c03-hash-tables',title='Hash Tables',used=['p01-two-sum','p02-longest-substring','p20-lru-cache'],scenes=[
 S('title',['This lesson explains hash tables, the most useful data structure in coding interviews.'],title='Hash Tables',sub='The coat check of computer science'),
 S('analogy',['Think of a coat check at a theater.','You hand over your coat and get a ticket number.','Later you show the ticket, and the attendant walks straight to that hook. No searching through every coat.','A hash table does the same thing: a hash function turns your key into a hook number.'],text='A coat check: your key is turned into a hook number (hashing), so finding your coat later is instant.',icons=['key','hash()','bucket','value']),
 S('hash',['Here we have eight buckets, numbered zero to seven.','To store the key seventeen, we compute seventeen mod eight, which is one. It goes in bucket one.','The key twenty five also gives one. That is a collision.','We simply chain it in a short list in the same bucket.','Lookups compute the bucket, then scan that tiny list.'],title='Hashing into buckets',buckets=8,states=[dict(table=[[],[],[],[],[],[],[],[]],note='8 empty buckets'),dict(key=17,b=1,calc='17 mod 8 = 1',table=[[],['17'],[],[],[],[],[],[]],note='17 → bucket 1'),dict(key=25,b=1,calc='25 mod 8 = 1',table=[[],['17','25'],[],[],[],[],[],[]],note='collision → chain'),dict(key=6,b=6,calc='6 mod 8 = 6',table=[[],['17','25'],[],[],[],[],['6'],[]],note='6 → bucket 6')]),
 S('bullets',['On average, insert, lookup, and delete are all O of one.','The worst case is O of n, if every key lands in the same bucket.','To keep chains short, the table grows and rehashes when it gets too full. That threshold is called the load factor.','In C plus plus this is unordered map. In Java it is HashMap. In C sharp it is Dictionary.'],title='Costs',items=['Average O(1) insert / lookup / delete','Worst case O(n): everything collides','Resize when load factor gets high','C++ unordered_map • Java HashMap • C# Dictionary']),
 S('array',['Here is how Two Sum uses a hash table.','We walk the array once. For each number we ask the table: have I already seen the partner, target minus me?','For two, we need seven. Not there yet, so we store two.','For seven, we need two. The table says yes, at index zero. Done in one pass.'],title='Two Sum with a map',states=[dict(a=[2,7,11,15],ptr={'i':0},side={'need':7,'seen':'{}'},note='store 2 → 0'),dict(a=[2,7,11,15],ptr={'i':1},hl=[0,1],side={'need':2,'seen':'{2: 0}'},note='found partner at 0 → [0,1]')]),
 S('bullets',['A few systems notes for staff level interviews.','Hash tables have poor locality when chains are pointers, so open addressing is often faster.','Iteration order is not guaranteed, so never depend on it.','Under concurrency, shard the table or use a concurrent map instead of one big lock.'],title='Systems notes',items=['Open addressing → better cache locality','Iteration order is not stable','Concurrency: shard locks or lock-free maps','Hash flooding attacks → seeded hashes']),
 S('title',['Whenever you hear "have I seen this before?", reach for a hash table.'],title='Recap',sub='Key → bucket → value, O(1) on average'),
]))
# 4 STACKS & QUEUES
L.append(dict(id='c04-stacks-queues',title='Stacks & Queues',used=['p04-valid-parentheses','p05-daily-temperatures','p08-level-order','p21-ring-buffer'],scenes=[
 S('title',['Stacks and queues are two simple ways to line things up. Interviews use them constantly.'],title='Stacks & Queues',sub='Plates and lines'),
 S('analogy',['A stack is a pile of plates. You add to the top and take from the top. Last in, first out.','A queue is the line at a coffee shop. You join at the back and get served at the front. First in, first out.'],text='Stack = pile of plates (last in, first out). Queue = coffee line (first in, first out).',icons=['push','pop','enqueue','dequeue']),
 S('stack',['Watch a stack check brackets.','We see an opening curly brace, so we push it.','Then an opening square bracket, push.','A closing square bracket must match the top plate. It does, so we pop.','The closing curly brace matches the new top. Pop. The pile is empty, so the string is valid.'],title='Stack: bracket checking',states=[dict(items=['{'],note='push {'),dict(items=['{','['],note='push ['),dict(items=['{'],note='] matches [ → pop'),dict(items=[],note='} matches { → valid!')]),
 S('array',['A special trick is the monotonic stack: a stack kept in sorted order.','For daily temperatures, the stack holds days still waiting for a warmer day.','When a hotter day arrives, it pops every colder waiting day and gives them their answer.','Each day is pushed once and popped once, so the whole thing is linear.'],title='Monotonic stack',states=[dict(a=[73,74,75,71,69,72,76,73],ptr={'i':2},side={'stack':'[75]'},note='waiting days are decreasing'),dict(a=[73,74,75,71,69,72,76,73],ptr={'i':4},side={'stack':'[75, 71, 69]'}),dict(a=[73,74,75,71,69,72,76,73],ptr={'i':5},hl=[3,4],side={'stack':'[75, 72]'},note='72 resolves 69 and 71'),dict(a=[73,74,75,71,69,72,76,73],ptr={'i':6},hl=[2,5],side={'stack':'[76]'},note='76 resolves 72 and 75')]),
 S('queue',['Now a queue.','Tasks join at the back.','The front task is served and leaves.','Breadth first search uses a queue so that nodes are processed in the order they were discovered, level by level.'],title='Queue: first in, first out',states=[dict(items=['A'],note='enqueue A'),dict(items=['A','B','C'],note='enqueue B, C'),dict(items=['B','C'],note='dequeue A'),dict(items=['B','C','D'],note='enqueue D')]),
 S('bullets',['In driver code you use queues all the time, as ring buffers.','A ring buffer is a fixed array where the head and tail indexes wrap around using modulo.','Nothing is ever copied or shifted, so every operation is O of one.','With one producer and one consumer, it can even be made lock free using atomic head and tail indexes.'],title='Ring buffers (your world)',items=['Fixed array + head + tail','Indexes wrap with % capacity','O(1), no shifting, no allocation','SPSC lock-free with atomics (acquire/release)']),
 S('title',['Stacks for "most recent unfinished thing", queues for "oldest first".'],title='Recap',sub='Stack = LIFO • Queue = FIFO • Ring buffer = queue in a circle'),
]))
# 5 LINKED LISTS
L.append(dict(id='c05-linked-lists',title='Linked Lists',used=['p06-reverse-list','p20-lru-cache'],scenes=[
 S('title',['Linked lists are chains of nodes connected by pointers. You have seen them in kernel code as list head.'],title='Linked Lists',sub='A conga line of nodes'),
 S('analogy',['Picture a conga line. Each dancer holds the shoulder of the next person.','To find the fifth dancer, you must start at the front and walk. There is no locker number.','But adding a dancer in the middle is easy: two people just change who they hold.'],text='A conga line: each node holds the next. Walking to the k-th is slow, but splicing someone in is instant.',icons=['walk O(n)','splice O(1)']),
 S('list',['Here is a list one, two, three, four.','Each box stores a value and a pointer to the next box.','The last pointer is null, shown as an empty set symbol.','To reach node four, you follow three arrows.'],title='Nodes and next pointers',states=[dict(nodes=[1,2,3,4],labels={'head':0}),dict(nodes=[1,2,3,4],labels={'head':0},hl=[3],note='reaching 4 takes 3 hops → O(n)')]),
 S('list',['Now let us reverse it in place, the classic interview question.','We use three pointers: previous, current, and next.','Save next, so we do not lose the rest of the line.','Point current backwards at previous.','Then move previous and current one step forward.','Repeat until current falls off the end. Previous is the new head.'],title='Reversing with three pointers',states=[dict(nodes=[1,2,3,4],next=[1,2,3,-1],labels={'cur':0},note='prev = ∅'),dict(nodes=[1,2,3,4],next=[-1,2,3,-1],labels={'prev':0,'cur':1},hl=[0],note='1 now points back'),dict(nodes=[1,2,3,4],next=[-1,0,3,-1],labels={'prev':1,'cur':2},hl=[1]),dict(nodes=[1,2,3,4],next=[-1,0,1,-1],labels={'prev':2,'cur':3},hl=[2]),dict(nodes=[1,2,3,4],next=[-1,0,1,2],labels={'prev':3},hl=[3],note='return prev = 4')]),
 S('bullets',['A doubly linked list adds a previous pointer, so you can unlink any node in O of one if you hold it.','That is exactly how an LRU cache moves an item to the front.','Sentinel, or dummy, nodes at both ends remove most null checks.','The cost: poor cache locality, because nodes are scattered in memory.'],title='Doubly linked & sentinels',items=['prev + next → O(1) unlink','LRU cache = hash map + doubly linked list','Dummy head/tail removes edge cases','Downside: scattered memory, cache misses']),
 S('title',['Draw the boxes and arrows before you code. Most linked list bugs are lost pointers.'],title='Recap',sub='Save next • flip • advance'),
]))
# 6 RECURSION & CALL STACK
L.append(dict(id='c06-recursion-call-stack',title='Recursion & the Call Stack',used=['p07-validate-bst','p10-islands','p17-subsets','p13-redundant-connection'],scenes=[
 S('title',['This is one of the most important lessons. Recursion, and the call stack that makes it work.'],title='Recursion & the Call Stack',sub='Functions that call themselves'),
 S('analogy',['Imagine Russian nesting dolls.','To find the smallest doll, you open one, and inside is a smaller version of the same problem.','You keep opening until you hit the tiny solid doll. That is the base case.','Then you close the dolls back up in reverse order. That is the function returning.'],text='Nesting dolls: open a doll, find a smaller one inside (recursive call), stop at the solid one (base case), then close them back up (returns).',icons=['call','call','base','return']),
 S('callstack',['Every function call gets a frame on the call stack, holding its local variables and where to return.','Let us compute factorial of three.','Factorial of three calls factorial of two. A new frame is pushed on top.','Factorial of two calls factorial of one. Another frame.','Factorial of one is the base case. It returns one.','Now frames pop off: two times one is two, then three times two is six.'],title='factorial(3)',states=[dict(frames=['main()']),dict(frames=['main()','fact(3)']),dict(frames=['main()','fact(3)','fact(2)']),dict(frames=['main()','fact(3)','fact(2)','fact(1) → base']),dict(frames=['main()','fact(3)','fact(2)'],ret='fact(1) = 1'),dict(frames=['main()','fact(3)'],ret='fact(2) = 2 × 1 = 2'),dict(frames=['main()'],ret='fact(3) = 3 × 2 = 6')]),
 S('tree',['On a tree, recursion follows the branches.','To validate a binary search tree, each call receives an allowed range.','Going left, the upper limit shrinks to the parent value. Going right, the lower limit rises.','Watch the stack grow as we go down, and shrink as calls return.','At node three, the range is five to six, and three is outside it. So the answer is false.'],title='Recursion on a tree',tree=[5,4,6,None,None,3,7],states=[dict(hl=[5],frames=['dfs(5, −∞, ∞)']),dict(hl=[4],ok=[5],frames=['dfs(5, −∞, ∞)','dfs(4, −∞, 5)']),dict(hl=[6],ok=[5,4],frames=['dfs(5, −∞, ∞)','dfs(6, 5, ∞)']),dict(bad=[3],ok=[5,4,6],frames=['dfs(5, −∞, ∞)','dfs(6, 5, ∞)','dfs(3, 5, 6)'],note='3 is not in (5, 6) → false')]),
 S('bullets',['Every recursive function needs two parts: a base case that stops, and a step that makes the problem smaller.','The call stack has limited size. A recursion depth of a million can crash with a stack overflow.','In kernel code the stack is only a few kilobytes, so recursion is usually avoided there.','You can always convert recursion into a loop with your own explicit stack.'],title='Rules and dangers',items=['Base case + smaller step','Depth = stack memory (O(h))','Kernel stacks are tiny (8–16 KB)','Convert to loop + explicit stack when deep']),
 S('title',['In this course every recursive problem has an execution visualizer. Press step and watch frames push and pop.'],title='Recap',sub='Frames push on call, pop on return'),
]))
# 7 TREES & BST
L.append(dict(id='c07-trees-bst',title='Trees & Binary Search Trees',used=['p07-validate-bst','p08-level-order','p14-trie'],scenes=[
 S('title',['Trees are everywhere: file systems, device trees, PCIe topologies, and the DOM in a browser.'],title='Trees & Binary Search Trees',sub='Family trees for data'),
 S('analogy',['A tree is like a company org chart.','There is one root at the top, the CEO. Each person can have reports below them, called children.','People with no reports are leaves.','A binary tree means every person has at most two reports: a left and a right.'],text='An org chart: one root, each node has children, nodes with no children are leaves. Binary = at most two children.',icons=['root','children','leaves']),
 S('tree',['A binary search tree adds one rule.','Everything on the left of a node is smaller, and everything on the right is larger.','So to find six, start at the root eight. Six is smaller, go left to four.','Six is larger than four, go right. Found it in three steps.','If the tree is balanced, a search takes about log n steps.'],title='BST search for 6',tree=[8,4,12,2,6,10,14],states=[dict(hl=[8],note='6 < 8 → go left'),dict(ok=[8],hl=[4],note='6 > 4 → go right'),dict(ok=[8,4],hl=[6],note='found in 3 steps = O(log n)')]),
 S('tree',['There are classic ways to walk a tree.','Depth first goes all the way down one branch before backing up. In-order depth first on a BST visits values in sorted order.','Breadth first visits level by level using a queue: eight, then four and twelve, then the bottom row.'],title='Traversals',tree=[8,4,12,2,6,10,14],states=[dict(hl=[2],note='in-order: 2'),dict(ok=[2],hl=[4],note='2, 4'),dict(ok=[2,4,6],hl=[8],note='2, 4, 6, 8 … sorted!'),dict(hl=[8],note='BFS level 0: 8'),dict(ok=[8],hl=[4,12],note='level 1: 4, 12'),dict(ok=[8,4,12],hl=[2,6,10,14],note='level 2')]),
 S('bullets',['Keep these costs in mind.','Balanced trees, like red black trees, give O of log n search, insert, and delete. std map and Java TreeMap use them.','An unbalanced tree can degrade into a linked list, with O of n operations.','Tree recursion uses stack memory equal to the height of the tree.'],title='Costs',items=['Balanced: O(log n) search/insert/delete','std::map, TreeMap, SortedDictionary = red-black trees','Skewed tree → O(n) (a linked list)','Recursion depth = tree height']),
 S('title',['Practice Validate BST and Level Order Traversal next, and watch the tree light up step by step.'],title='Recap',sub='Left smaller, right larger • DFS vs BFS'),
]))
# 8 HEAPS
L.append(dict(id='c08-heaps',title='Heaps & Priority Queues',used=['p09-kth-largest','p12-network-delay'],scenes=[
 S('title',['A heap gives you the smallest, or the largest, item instantly. It powers schedulers and top k problems.'],title='Heaps & Priority Queues',sub='Always know who is most urgent'),
 S('analogy',['Think of a hospital emergency room.','Patients do not wait in arrival order. The most urgent patient is always seen next.','The triage nurse does not fully sort everyone, they just make sure the most urgent person is at the front.','That partial order is cheap to maintain, and that is the idea of a heap.'],text='An emergency room: the most urgent patient is always next. No full sort needed, just "who is on top?"',icons=['peek O(1)','push O(log n)','pop O(log n)']),
 S('heap',['A min heap is a tree stored inside an array.','The rule: every parent is smaller than or equal to its children. So the smallest is always at index zero, the root.','The children of index i live at two i plus one and two i plus two. No pointers needed.'],title='Min-heap = tree in an array',states=[dict(a=[1,3,2,7,4,5],hl=[0],note='smallest at index 0'),dict(a=[1,3,2,7,4,5],hl=[1,3,4],note='children of i: 2i+1, 2i+2')]),
 S('heap',['To insert zero, place it at the end of the array.','Then sift it up: while it is smaller than its parent, swap them.','It swaps with two, then with one, and becomes the new root.','At most log n swaps, because the tree is balanced.'],title='Push: sift up',states=[dict(a=[1,3,2,7,4,5,0],hl=[6],note='append 0'),dict(a=[1,3,0,7,4,5,2],hl=[2],note='swap with parent 2'),dict(a=[0,3,1,7,4,5,2],hl=[0],note='swap with parent 1 → root')]),
 S('array',['Here is a top k trick.','To find the second largest number, keep a min heap of size two.','Every new number goes in. If the heap grows past two, pop the smallest.','At the end, the top of the heap is the answer. This costs n log k, great for streams of latency samples.'],title='Kth largest with a size-k heap',states=[dict(a=[3,2,1,5,6,4],ptr={'i':1},side={'heap':'[2, 3]'}),dict(a=[3,2,1,5,6,4],ptr={'i':3},side={'heap':'[3, 5]'}),dict(a=[3,2,1,5,6,4],ptr={'i':5},side={'heap':'[5, 6]'},note='top = 5 = 2nd largest')]),
 S('bullets',['In C plus plus, priority queue is a max heap by default. Pass greater to make it a min heap.','In Java, PriorityQueue is a min heap by default.','In C sharp, PriorityQueue takes an element and a priority, and dequeues the lowest priority first.','Dijkstra\'s shortest path algorithm and OS schedulers both rely on heaps.'],title='Language notes',items=['C++ priority_queue: max-heap (use greater<> for min)','Java PriorityQueue: min-heap','C# PriorityQueue<T, P>: lowest priority first','Used by Dijkstra, schedulers, timers']),
 S('title',['Whenever you hear top k, smallest so far, or next event, think heap.'],title='Recap',sub='Parent ≤ children • O(log n) push/pop • O(1) peek'),
]))
# 9 GRAPHS
L.append(dict(id='c09-graphs-bfs-dfs',title='Graphs: BFS, DFS & Topological Order',used=['p10-islands','p11-course-schedule','p12-network-delay','p13-redundant-connection'],scenes=[
 S('title',['Graphs model networks: servers and switches, build dependencies, road maps, and robot occupancy grids.'],title='Graphs: BFS, DFS & Topological Order',sub='Dots and lines'),
 S('analogy',['A graph is just dots and lines.','The dots are nodes, like cities. The lines are edges, like roads.','Roads can be one way, which makes a directed graph, or carry a cost, like travel time, which makes a weighted graph.'],text='Cities (nodes) and roads (edges). One-way roads = directed. Travel times = weighted.',icons=['nodes','edges','directed','weighted']),
 S('graph',['Breadth first search explores like ripples in a pond.','Start at A. First visit every neighbor one step away: B and C.','Then everything two steps away: D and E.','Because it goes level by level, BFS finds the shortest path when every edge has the same cost.'],title='BFS = ripples (uses a queue)',nodes=[['A',120,200],['B',300,110],['C',300,290],['D',500,110],['E',500,290],['F',690,200]],edges=[[0,1],[0,2],[1,3],[2,4],[3,5],[4,5],[1,2]],states=[dict(hl=[0],side={'queue':'[A]'}),dict(ok=[0],hl=[1,2],side={'queue':'[B, C]'}),dict(ok=[0,1,2],hl=[3,4],side={'queue':'[D, E]'}),dict(ok=[0,1,2,3,4],hl=[5],side={'queue':'[F]'},note='levels = shortest hops')]),
 S('graph',['Depth first search is like exploring a maze with one hand on the wall.','Go as deep as possible: A, then B, then D, then F.','When you hit a dead end, back up and try the next unexplored path.','DFS uses recursion or an explicit stack, and it is perfect for flood fill and cycle detection.'],title='DFS = maze explorer (uses a stack)',nodes=[['A',120,200],['B',300,110],['C',300,290],['D',500,110],['E',500,290],['F',690,200]],edges=[[0,1],[0,2],[1,3],[2,4],[3,5],[4,5],[1,2]],states=[dict(hl=[0],side={'stack':'[A]'}),dict(ok=[0],hl=[1],he=[[0,1]],side={'stack':'[A, B]'}),dict(ok=[0,1],hl=[3],he=[[0,1],[1,3]],side={'stack':'[A, B, D]'}),dict(ok=[0,1,3],hl=[5],he=[[0,1],[1,3],[3,5]],side={'stack':'[A, B, D, F]'}),dict(ok=[0,1,3,5],hl=[4],he=[[0,1],[1,3],[3,5],[5,4]],side={'stack':'[A, B, D, F, E]'},note='then back up')]),
 S('graph',['Topological sort orders tasks so every dependency comes first, like building drivers before the app that uses them.','Count how many arrows point into each node. Start with nodes that have zero.','Each time you finish a node, remove its arrows. New zeros become ready.','If nodes are left over and none are ready, there is a cycle.'],title='Topological order (Kahn)',directed=True,nodes=[['bus',120,200],['i2c',320,110],['clk',320,290],['sensor',540,200],['app',740,200]],edges=[[0,1],[0,2],[1,3],[2,3],[3,4]],states=[dict(hl=[0],side={'ready':'[bus]'}),dict(ok=[0],hl=[1,2],side={'ready':'[i2c, clk]'}),dict(ok=[0,1,2],hl=[3],side={'ready':'[sensor]'}),dict(ok=[0,1,2,3],hl=[4],side={'order':'bus, i2c, clk, sensor, app'})]),
 S('bullets',['Quick guide.','Unweighted shortest path: BFS.','Weighted, non negative shortest path: Dijkstra with a heap.','Connected groups or flood fill: DFS, BFS, or union find.','Dependencies and ordering: topological sort.','Always track visited nodes, or you will loop forever.'],title='Which algorithm?',items=['Shortest hops → BFS','Weighted shortest path → Dijkstra (heap)','Components / flood fill → DFS or union-find','Dependencies → topological sort','Always keep a visited set']),
 S('title',['Graphs look scary, but most graph problems are BFS or DFS with a visited set.'],title='Recap',sub='BFS = queue • DFS = stack • Topo = in-degrees'),
]))
# 10 DP
L.append(dict(id='c10-dynamic-programming',title='Dynamic Programming',used=['p18-coin-change','p19-counting-bits'],scenes=[
 S('title',['Dynamic programming sounds fancy, but it just means: do not solve the same small problem twice.'],title='Dynamic Programming',sub='Remember answers to smaller questions'),
 S('analogy',['Imagine climbing a staircase and writing the answer to each step on a sticky note.','To answer step ten, you read the notes on steps nine and eight, instead of climbing from the bottom again.','Those sticky notes are the DP table.'],text='Sticky notes on a staircase: each step\'s answer is built from the notes on lower steps.',icons=['subproblem','store','reuse']),
 S('bullets',['Use DP when two things are true.','First, the big answer can be built from answers to smaller versions of the same question. That is called optimal substructure.','Second, the same smaller questions come up again and again. That is called overlapping subproblems.','Then pick a state, write the recurrence, and fill a table from small to big.'],title='When to use DP',items=['Big answer built from smaller answers','Same subproblems repeat','Define the state: dp[a] = ?','Write the recurrence, fill small → big']),
 S('grid',['Let us solve coin change: make six using coins one, three, and four, with the fewest coins.','Greedy would grab four, then one, then one: three coins. But three plus three is only two coins!','The DP table stores the best answer for each amount from zero to six.','For each amount a, try each coin as the last coin: one plus dp of a minus that coin.','Watch the table fill. dp of six is the minimum of dp five, dp three, and dp two, plus one. That is two.'],title='Coin change: coins [1, 3, 4], amount 6',colLabels=['0','1','2','3','4','5','6'],states=[dict(g=[[0,'∞','∞','∞','∞','∞','∞']],hl=[[0,0]],note='dp[0] = 0'),dict(g=[[0,1,2,'∞','∞','∞','∞']],hl=[[0,2]],note='dp[2] = dp[1] + 1 = 2'),dict(g=[[0,1,2,1,1,'∞','∞']],hl=[[0,3],[0,4]],note='coins 3 and 4 make dp = 1'),dict(g=[[0,1,2,1,1,2,'∞']],hl=[[0,5]],note='dp[5] = dp[4] + 1 = 2'),dict(g=[[0,1,2,1,1,2,2]],hl=[[0,6]],ok=[[0,3]],note='dp[6] = dp[3] + 1 = 2 (3 + 3)')]),
 S('bullets',['There are two styles.','Top down: write the recursion, then add a cache, called memoization.','Bottom up: fill an array in order, with no recursion and no stack risk.','Both have the same complexity. Here, amount times number of coins.'],title='Top-down vs bottom-up',items=['Top-down = recursion + memo cache','Bottom-up = loop filling a table','Same complexity: O(amount × coins)','Bottom-up avoids deep stacks']),
 S('title',['The hardest part of DP is naming the state. Practice coin change and counting bits, then you will see the pattern everywhere.'],title='Recap',sub='State • recurrence • base case • order'),
]))
