X={
'c02-arrays-pointers':[S('array',['One more classic: binary search on a rotated array, like a log ring buffer that wrapped around.','Pick the middle. At least one half is still in sorted order.','If the target falls inside the sorted half, keep that half. Otherwise keep the other one.','Each step throws away half the array, so it costs log n steps.'],title='Binary search on a wrapped array',states=[dict(a=[4,5,6,7,0,1,2],ptr={'lo':0,'mid':3,'hi':6},note='left half [4..7] sorted; 0 not inside'),dict(a=[4,5,6,7,0,1,2],ptr={'lo':4,'mid':5,'hi':6},note='left half [0,1] sorted; 0 inside'),dict(a=[4,5,6,7,0,1,2],ptr={'lo':4,'mid':4,'hi':4},hl=[4],note='found at index 4')])],
'c03-hash-tables':[S('bullets',['In the interview, say out loud why a hash map fits: you need fast membership or counting.','Mention the trade: you spend memory to buy time.','And remember the classic bug in Two Sum: check for the partner before inserting yourself.'],title='Interview tips',items=['Say why: fast "seen before?" or counting','Trade memory for time','Check before insert (Two Sum [3,3])'])],
'c04-stacks-queues':[S('bullets',['Common interview mistakes with stacks and queues.','Popping from an empty stack. Always check first.','Forgetting to check that the stack is empty at the very end of a bracket check.','Using a Java Stack class instead of ArrayDeque, which is faster and the modern choice.','And for ring buffers, mixing up full and empty when head equals tail. Keep a count, or leave one slot unused.'],title='Pitfalls',items=['Check empty before pop','Final emptiness check','Java: prefer ArrayDeque','Ring buffer: full vs empty ambiguity'])],
'c05-linked-lists':[S('list',['A classic trick is the fast and slow pointer, sometimes called the tortoise and the hare.','The slow pointer moves one step, the fast pointer moves two.','When fast reaches the end, slow is exactly in the middle.','If the list has a cycle, fast will eventually lap slow and they will meet. That is how you detect a loop in a corrupted descriptor chain.'],title='Fast & slow pointers',states=[dict(nodes=[1,2,3,4,5],labels={'slow':0,'fast':0}),dict(nodes=[1,2,3,4,5],labels={'slow':1,'fast':2}),dict(nodes=[1,2,3,4,5],labels={'slow':2,'fast':4},hl=[2],note='slow is the middle')]),
  S('bullets',['Interview tips for linked lists.','Use a dummy head node when the head itself might change, like when deleting or merging.','Draw three or four boxes on the whiteboard and update the arrows by hand before writing code.','And in C plus plus, think about who owns each node, so you do not leak memory or free a node twice.'],title='Interview tips',items=['Dummy head when head can change','Draw boxes, move arrows by hand','C++: ownership — leaks and double frees'])],
'c06-recursion-call-stack':[S('bullets',['Backtracking is recursion that undoes its last choice.','Choose an option, explore deeper, then un-choose it before trying the next one.','Subsets, permutations, and N queens all follow this template.'],title='Backtracking template',items=['choose → path.push(x)','explore → recurse','un-choose → path.pop()'])],
'c07-trees-bst':[S('tree',['A very common interview bug: checking only a node against its own children.','In this tree, three is less than six, so it looks fine locally.','But three sits in the right subtree of five, so it must be greater than five. The tree is not a valid BST.','The fix is to pass the allowed range down the recursion.'],title='The grandparent trap',tree=[5,4,6,None,None,3,7],states=[dict(hl=[6,3],note='3 < 6 looks fine locally…'),dict(hl=[5],bad=[3],note='…but 3 is in 5\'s right subtree → invalid')]),
  S('bullets',['A trie is a special tree for strings. Each edge is a letter, and paths spell words.','Words that share a prefix share the same nodes, like car and cat sharing c and a.','Search and prefix checks cost O of the word length, no matter how many words are stored.','Tries power autocomplete and symbol lookup in code search tools.'],title='Bonus: tries',items=['Edges are letters, paths are words','Shared prefixes share nodes','O(L) lookups','Autocomplete, code search'])],
'c08-heaps':[S('bullets',['Interview tips for heaps.','Say which way the heap points and why. For the k largest, you want a min heap, so you can evict the smallest.','Know that building a heap from an array takes only O of n, not n log n.','And mention quickselect as an alternative for one-off kth element queries.'],title='Interview tips',items=['Min-heap for k largest (evict smallest)','heapify is O(n)','Quickselect: average O(n)'])],
'c09-graphs-bfs-dfs':[S('bullets',['Graphs in your world.','A PCIe topology is a tree you walk with depth first search.','Device driver probe order is a topological sort.','A GPU cluster fabric is a weighted graph where shortest paths matter for collectives.'],title='Graphs in systems work',items=['PCIe enumeration → DFS on a tree','Driver probe order → topological sort','Cluster fabric → weighted shortest paths'])],
'c10-dynamic-programming':[S('array',['Counting bits is DP in disguise.','The number of one bits in i equals the count for i shifted right by one, plus the lowest bit.','Shifting right just drops the last bit, and we already know that smaller answer.','So each entry is one lookup and one addition.'],title='Counting bits: ans[i] = ans[i>>1] + (i & 1)',states=[dict(a=[0,1,1,2,1,2,2,3,1],ptr={'i':5},hl=[2,5],note='5 = 101 → ans[2] + 1 = 2'),dict(a=[0,1,1,2,1,2,2,3,1],ptr={'i':7},hl=[3,7],note='7 = 111 → ans[3] + 1 = 3')])],
}
